from typing import Any, Dict, Optional
import os
import json
from enum import Enum

# Custom exception for configuration validation errors
class ConfigValidationError(ValueError):
    """Raised when a config value fails validation."""
    def __init__(self, key: str, value: Any, message: str):
        self.key = key
        self.value = value
        self.message = message
        super().__init__(f"{key}: {message} (value: {value})")

# Define the full schema based on the specification
_SCHEMA: dict[str, dict] = {
    "queue_url": {
        "type": "string",
        "default": "redis://localhost:6379/0",
        "env_var": "CELERY_QUEUE_URL",
        "validation": {"non-empty string": True},
        "description": "URL of the message queue"
    },
    "concurrency": {
        "type": "int",
        "default": 3,
        "env_var": "CELERY_CONCURRENCY",
        "validation": {"range": [1, 32]},
        "description": "Number of concurrent workers; must be 1-32"
    },
    "max_retries": {
        "type": "int",
        "default": 8,
        "env_var": "CELERY_MAX_RETRIES",
        "validation": {"range": [0, 20]},
        "description": "Maximum retry attempts per job; must be 0-20"
    },
    "retry_backoff_seconds": {
        "type": "int",
        "default": 1,
        "env_var": "CELERY_RETRY_BACKOFF",
        "validation": {"range": [1, 300]},
        "description": "Seconds to wait between retries; must be 1-300"
    },
    "job_timeout": {
        "type": "int",
        "default": 300,
        "env_var": "CELERY_JOB_TIMEOUT",
        "validation": {"range": [1, 3600]},
        "description": "Job execution timeout in seconds; must be 1-3600"
    },
    "log_level": {
        "type": "enum",
        "default": "INFO",
        "env_var": "CELERY_LOG_LEVEL",
        "validation": {"allowed": ["DEBUG", "INFO", "WARN"]},
        "description": "Logging verbosity; one of ['DEBUG', 'INFO', 'WARN']"
    },
    "dead_letter_queue": {
        "type": "bool",
        "default": True,
        "env_var": "CELERY_DEAD_LETTER",
        "validation": {"bool": True},
        "description": "Route failed jobs to dead letter queue"
    },
    "heartbeat_interval": {
        "type": "int",
        "default": 60,
        "env_var": "CELERY_HEARTBEAT",
        "validation": {"range": [5, 300]},
        "description": "Worker heartbeat interval seconds; must be 5-300"
    },
    "prefetch_count": {
        "type": "int",
        "default": 10,
        "env_var": "CELERY_PREFETCH",
        "validation": {"range": [1, 100]},
        "description": "Number of messages to prefetch; must be 1-100"
    },
    "ack_on_failure": {
        "type": "bool",
        "default": False,
        "env_var": "CELERY_ACK_ON_FAILURE",
        "validation": {"bool": True},
        "description": "Acknowledge message even on job failure"
    },
    "metrics_enabled": {
        "type": "bool",
        "default": True,
        "env_var": "CELERY_METRICS",
        "validation": {"bool": True},
        "description": "Enable Prometheus metrics"
    }
}

def get_schema() -> dict:
    """Return the config schema."""
    return _SCHEMA

def load_config(
    config_file: str | None = None,
    env_vars: dict | None = None,
    cli_args: dict | None = None,
) -> dict:
    """Load and validate configuration from all sources in priority order.

    Args:
        config_file: Path to a JSON config file (optional).
        env_vars: Dict of environment variables (defaults to os.environ).
        cli_args: Dict of CLI arguments — highest priority.

    Returns:
        A dict with all config keys populated, validated, and type-coerced.

    Raises:
        ConfigValidationError: If any value fails validation.
        FileNotFoundError: If config_file is specified but does not exist.
    """
    # Initialize config with defaults
    config = {key: value["default"] for key, value in _SCHEMA.items()}

    # Apply CLI arguments (highest priority)
    if cli_args:
        for key, value in cli_args.items():
            if key in config:
                config[key] = value

    # Apply environment variables
    if env_vars is None:
        env_vars = os.environ
    for key, value in env_vars.items():
        if key in _SCHEMA:
            config[key] = value

    # Apply config file (lowest priority)
    if config_file:
        try:
            with open(config_file, "r") as f:
                file_config = json.load(f)
            for key, value in file_config.items():
                if key in config:
                    config[key] = value
        except FileNotFoundError:
            raise FileNotFoundError(f"Config file not found: {config_file}")
        except json.JSONDecodeError:
            raise ValueError(f"Invalid JSON in config file: {config_file}")

    # Validate and coerce each value
    for key, value in config.items():
        config[key] = validate_value(key, value)

    return config

def validate_value(key: str, value: Any) -> Any:
    """Validate and coerce a single value against the schema for `key`.

    Returns the coerced value.
    Raises ConfigValidationError if invalid.
    """
    schema = _SCHEMA[key]
    type_ = schema["type"]
    validation = schema.get("validation", {})

    # Coerce value based on type
    if type_ == "int":
        try:
            coerced = int(value)
        except (ValueError, TypeError):
            raise ConfigValidationError(key, value, "Value must be an integer")
    elif type_ == "float":
        try:
            coerced = float(value)
        except (ValueError, TypeError):
            raise ConfigValidationError(key, value, "Value must be a float")
    elif type_ == "bool":
        if isinstance(value, bool):
            coerced = value
        elif isinstance(value, str):
            value = value.lower()
            if value in ["true", "yes", "on", "1"]:
                coerced = True
            elif value in ["false", "no", "off", "0"]:
                coerced = False
            else:
                raise ConfigValidationError(key, value, "Value must be a boolean (true/false, yes/no, on/off, 1/0)")
        else:
            raise ConfigValidationError(key, value, "Value must be a boolean (true/false, yes/no, on/off, 1/0)")
    elif type_ == "enum":
        allowed = validation.get("allowed", [])
        if not allowed:
            raise ConfigValidationError(key, value, "Enum type requires allowed values in schema")
        try:
            coerced = value.upper()
        except (ValueError, TypeError):
            raise ConfigValidationError(key, value, "Value must be a valid enum value")
        if coerced not in allowed:
            raise ConfigValidationError(key, value, f"Value must be one of {allowed}")
    elif type_ == "string":
        coerced = str(value)
    else:
        raise ConfigValidationError(key, value, f"Unsupported type: {type_}")

    # Validate range or allowed values
    if type_ in ["int", "float"]:
        if "range" in validation:
            min_val, max_val = validation["range"]
            if not (min_val <= coerced <= max_val):
                raise ConfigValidationError(key, coerced, f"Value must be between {min_val} and {max_val}")
    elif type_ == "enum":
        # Already validated above
        pass
    elif type_ == "bool":
        # Already validated above
        pass
    elif type_ == "string":
        if "non-empty string" in validation:
            if not coerced.strip():
                raise ConfigValidationError(key, coerced, "Value must be a non-empty string")
    else:
        # No additional validation needed
        pass

    return coerced
